// Design Circular Queue with fixed capacity
struct MyCircularQueue {
    private var queue = AnimatedQueue<Int>()
    private let capacity: Int
    private var lastInserted = -1

    init(k: Int) {
        self.capacity = k
    }

    mutating func enQueue(_ value: Int) -> Bool {
        if queue.count >= capacity {
            return false
        }
        queue.enqueue(value)
        lastInserted = value
        return true
    }

    mutating func deQueue() -> Bool {
        if queue.isEmpty {
            return false
        }
        queue.dequeue()
        return true
    }

    func Front() -> Int {
        return queue.peek() ?? -1
    }

    func Rear() -> Int {
        return queue.isEmpty ? -1 : lastInserted
    }

    func isEmpty() -> Bool {
        return queue.isEmpty
    }

    func isFull() -> Bool {
        return queue.count == capacity
    }
}

var circularQueue = MyCircularQueue(k: 3)
_ = circularQueue.enQueue(1)
_ = circularQueue.enQueue(2)
_ = circularQueue.enQueue(3)
_ = circularQueue.enQueue(4)
_ = circularQueue.deQueue()
_ = circularQueue.enQueue(4)
